<?php ?><div class="blog-grid"><?php if(have_posts()):while(have_posts()):the_post();?><a href="<?php the_permalink();?>" class="blog-card"><div class="blog-card__img"><?php if(has_post_thumbnail()):the_post_thumbnail('medium',['loading'=>'lazy']);else:?><img src="https://images.unsplash.com/photo-1673300881006-3bd384aa1949?w=300&h=200&fit=crop&auto=format" alt="" loading="lazy"><?php endif;?></div><div class="blog-card__body"><div class="blog-card__meta"><span><?php echo get_the_date();?></span><span>·</span><span><?php the_author();?></span></div><h2 class="blog-card__title"><?php the_title();?></h2></div></a><?php endwhile;else:get_template_part('template-parts/content','none');endif;?></div>